    refuseResult = #{refuseResult},
    workSummary = #{workSummary}
WHERE id = #{id}

mapper.select:
SELECT *
FROM officehourevent
WHERE teacher = #{teacherId}
  AND appointmentDate = #{appointmentDate}
  AND (
    (startTime < #{endTime} AND endTime > #{startTime})
    )

